87	/**
88	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
89	 * plus any control-panel/app install script and selected add-ons. Long installs
90	 * run in the background so the VM reports ready promptly.
91	 */
92	function buildCloudInit(server: any): string {
93	  const addons = (server.addons ?? {}) as {
94	    malwareScanner?: boolean;
95	    dailyBackup?: boolean;
96	    docker?: boolean;
97	    claudeCode?: boolean;
98	  };
99	  const setup: string[] = [];
100	
101	  // Pre-bake Claude Code (Anthropic CLI) on every server unless explicitly opted
102	  // out. Customers SSH in and run `claude` using their own subscription or API
103	  // key — no setup on our side, zero token cost to us. Installs run in the
104	  // background (nohup below) so the VM still reports ready quickly.
105	  if (addons.claudeCode !== false) {
106	    setup.push(
107	      "# --- Nxeon: pre-install Claude Code (Anthropic CLI) ---",
108	      "(apt-get install -y git curl ca-certificates || dnf install -y git curl ca-certificates || true)",
109	      "if ! command -v node >/dev/null 2>&1; then " +
110	        "(curl -fsSL https://deb.nodesource.com/setup_20.x | bash - && apt-get install -y nodejs) || " +
111	        "(curl -fsSL https://rpm.nodesource.com/setup_20.x | bash - && dnf install -y nodejs) || " +
112	        "(apt-get install -y nodejs npm || true); fi",
113	      "npm install -g @anthropic-ai/claude-code || true",
114	      "command -v claude >/dev/null 2>&1 && echo 'Claude Code installed' >> /var/log/nxeon-setup.log || true",
115	    );
116	  }
117	
118	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
119	  if (addons.malwareScanner)
120	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
121	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
122	
123	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
124	
125	  // A friendly first-login guide + MOTD banner pointing at the portal hub.
126	  const welcome = [
127	    "# Welcome to your Nxeon server",
128	    "",
129	    "## Build anything with Claude Code — it's already installed",
130	    "",
131	    "1. You're already logged in. Just run:",
132	    "",
133	    "   claude",
134	    "",
135	    "2. Sign in once — either with your Claude subscription (Pro/Max) or an",
136	    "   Anthropic API key. See the step-by-step guide with screenshots at:",
137	    "",
138	    "   https://nxeon.cloud/dashboard/claude-code",
139	    "",
140	    "3. Then describe what you want in plain English, for example:",
141	    '   "Build a modern website for my coffee shop with a menu and contact form,',
142	    '    then run it and tell me the URL to preview it."',
143	    "",
144	    "Copy-paste starter prompts (spa site, booking app, REST API, Discord bot,",
145	    "and 20+ more) and how-to guides live in your portal at the link above.",
146	    "",
147	    "Happy building!",
148	  ].join("\n");
149	
150	  const motd = [
151	    "#!/bin/sh",
152	    'if [ -t 1 ]; then',
153	    '  printf "\\n  \\033[1mNxeon\\033[0m — Claude Code is pre-installed on this server.\\n"',
154	    '  printf "  Run \\033[1mclaude\\033[0m to start building. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
155	    '  printf "  Full walkthrough: \\033[2m~/START-WITH-CLAUDE.md\\033[0m\\n\\n"',
156	    "fi",
157	  ].join("\n");
158	
159	  return `#cloud-config
160	package_update: true
161	packages:
162	  - qemu-guest-agent
163	ssh_pwauth: true
164	disable_root: false
165	write_files:
166	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
167	    permissions: "0644"
168	    content: |
169	      PermitRootLogin yes
170	      PasswordAuthentication yes
171	  - path: /root/START-WITH-CLAUDE.md
172	    permissions: "0644"
173	    content: |
174	${indentBlock(welcome, 6)}
175	  - path: /etc/profile.d/nxeon-welcome.sh
176	    permissions: "0755"
177	    content: |
178	${indentBlock(motd, 6)}
179	  - path: /root/nxeon-setup.sh
180	    permissions: "0755"
181	    content: |
182	${indentBlock(script, 6)}
183	runcmd:
184	  - systemctl enable --now qemu-guest-agent
185	  - systemctl restart ssh || systemctl restart sshd
186	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
187	`;
188	}
189	
190	const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
191	const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";
192	
193	async function provision(job: Job) {
194	  const server = await loadServer(job);
195	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
196	
197	  if (SANDBOX) {
198	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
199	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
200	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
201	    const password = generatePassword();
202	    const ip = sandboxIp(vmid);
203	    await db.server.update({
204	      where: { id: server.id },
205	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
206	    });
207	    await notify(
208	      server.userId,
209	      `Server ${server.hostname} is ready`,
210	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
211	      `/dashboard/servers/${server.id}`
212	    );
213	    return;
214	  }
215	
216	  const { conn, row: nodeRow } = await nodeFor(server);
217	  const storage = server.plan.storageTier === "hdd"
218	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
219	    : nodeRow?.storageNvme ?? "vmdata";
220	
221	  const vmid = server.vmid ?? (await conn.nextVmid());
222	  const password = generatePassword();
223	
224	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
225	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
226	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
227	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
228	  const { getSettingBool: _settingBool } = await import("../lib/settings");
229	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
230	  if (wantDedicated && ovhConfigured()) {
231	    try {
232	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
233	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
234	      dedicated = await allocateDedicatedIp(server.id, vmid);
235	    } catch (e) {
236	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
237	    }
238	  }
239	  // Node-aware + transactionally-claimed allocation (passing the server id enables
240	  // the claim path, so two concurrent provisions can't pick the same IP/port).
241	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
242	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
243	
244	  await db.server.update({
245	    where: { id: server.id },
246	    data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
247	  });
248	
249	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
250	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
251	  // (worker restart mid-clone, or any transient failure in the steps below) would
252	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
253	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
254	  // the clone is idempotent, so skip it when the VM is already present.
255	  let vmAlreadyExists = false;
256	  try {
257	    await conn.vmStatus(vmid);
258	    vmAlreadyExists = true;
259	  } catch {
260	    vmAlreadyExists = false;
261	  }
262	  if (vmAlreadyExists) {
263	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
264	  } else {
265	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
266	      newid: vmid,
267	      name: server.hostname,
268	      full: 1,
269	      storage,
270	    });
271	    await conn.waitForTask(cloneUpid, 600_000);
272	  }
273	
274	  // Per-server cloud-init snippet (base + panel/app install + add-ons)
275	  const snippet = buildCloudInit(server);
276	  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
277	    console.error("[worker] snippet write failed", e)
278	  );
279	
280	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
281	  const sshkeys = keys.length
282	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
283	    : undefined;
284	  const cfg: Record<string, any> = {
285	    cores: server.plan.cpuCores,
286	    memory: server.plan.ramMB,
287	    ciuser: "root",
288	    cipassword: password,
289	    sshkeys,
290	    nameserver: "1.1.1.1 8.8.8.8",
291	    onboot: 1,
292	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
293	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
294	  };
295	  if (dedicated) {
296	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
297	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
298	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
299	  } else {
300	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
301	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
302	  }
303	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
304	
305	  // Provision at the EFFECTIVE size: the plan's allowance plus any extra disk the
306	  // customer bought as a deploy-time upsell, so the VM is born the right size and
307	  // no separate DISK_EXPAND job is needed on a fresh order.
308	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
309	    disk: "scsi0",
310	    size: `${effectiveDiskGB(server.plan.diskGB, server.extraDiskGB)}G`,
311	  });
312	
313	  if (!SANDBOX && !dedicated) await syncPortForwards();
314	
315	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
316	  await conn.waitForTask(startUpid);
317	
318	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
319	  const isImage = server.osTemplate.category !== "PLAIN_OS";
320	  const sshLine = dedicated
321	    ? `ssh root@${dedicated.address}`
322	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
323	  await notify(
324	    server.userId,
325	    `Server ${server.hostname} is ready`,
326	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
327	    `/dashboard/servers/${server.id}`
328	  );
329	}
