612	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
613	  const server = await loadServer(job);
614	  const payload = (job.payload ?? {}) as { name?: string };
615	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
616	  if (!name) throw new Error("snapshot: invalid name");
617	  if (SANDBOX) {
618	    await notify(
619	      server.userId,
620	      `Snapshot ${op} (sandbox): ${name}`,
621	      `Sandbox snapshot ${op} completed (no real VM was touched).`,
622	      `/dashboard/servers/${server.id}`
623	    );
624	    return;
625	  }
626	  const { conn } = await nodeFor(server);
627	  let upid: string;
628	  if (op === "create") {
629	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
630	  } else if (op === "delete") {
631	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
632	  } else {
633	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
634	  }
635	  await conn.waitForTask(upid, 600_000);
636	  if (op === "rollback") {
637	    // rollback leaves the VM stopped; bring it back if the server should be running
638	    const current = await db.server.findUnique({ where: { id: server.id } });
639	    if (current?.status === "RUNNING") {
640	      try {
641	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
642	        await conn.waitForTask(startUpid);
643	      } catch { /* may already be running */ }
644	    }
645	  }
646	}
