402	// ---------------------------------------------------------------------------
403	// Platform backups vs customer backups
404	// ---------------------------------------------------------------------------
405	//
406	// DATA LOSS PREVENTED (real, on this host, 2026-07-26): `scripts/backup-vms.sh`
407	// used to write the platform's own host-level disaster-recovery archives into the
408	// SAME Proxmox storage (`backup` -> /tank/backup/dump) that customers' on-demand
409	// backups land in, and `pruneBackups` below selected victims with nothing but
410	// `b.vmid === vmid`. So vmid 102 ended the 04:31 platform run holding two
411	// archives — the customer's own manual one from 2026-07-25 12:22 and the
412	// platform's 10 GB DR copy from 2026-07-26 04:31 — and the customer's very next
413	// click on "Create backup" (keep = CUSTOMER_BACKUP_KEEP = 2) would have deleted
414	// the platform's copy of their VM. Repeated across the fleet that silently
415	// destroys the entire bare-metal recovery set, one customer click at a time.
416	//
417	// The fix is three independent layers, in order of strength:
418	//
419	//  1. STRUCTURAL. `scripts/backup-vms.sh` now writes with `vzdump --dumpdir
420	//     /tank/backup/platform`, a directory that is NOT the `dump/` subdirectory of
421	//     any configured PVE storage. Proxmox only indexes `<storage-path>/dump`, so
422	//     platform archives have no `volid` at all: they cannot appear in the
423	//     `/storage/backup/content` listing this function iterates, and there is no
424	//     volid string that `DELETE /storage/backup/content/<volid>` could resolve to
425	//     them. Not "filtered out" — not addressable.
426	//  2. CHOKEPOINT. `deleteBackup` is the only function in the repo that issues a
427	//     storage-content DELETE (whole-repo grep: this file plus its single caller in
428	//     worker/index.ts). It re-derives protection for every volid immediately
429	//     before deleting and refuses on any of: the PVE `protected` attribute, the
430	//     platform notes marker, or the protection registry — and it fails CLOSED if
431	//     it cannot determine the answer.
432	//  3. MARKER + REGISTRY. If the platform job is ever pointed back at a shared PVE
433	//     storage (`NXEON_VM_BACKUP_STORAGE=backup`), it stamps each archive with
434	//     `--notes-template` carrying PLATFORM_BACKUP_MARKER and appends the volid to
435	//     PROTECTED_REGISTRY. Both are honoured below, which also covers the archives
436	//     already sitting in /tank/backup/dump from the 2026-07-26 04:31 run, written
437	//     before layer 1 existed.
438	
439	/** Where the platform's own whole-system vzdump archives live — outside every PVE storage. */
440	export const PLATFORM_BACKUP_DIR = process.env.NXEON_PLATFORM_BACKUP_DIR ?? "/tank/backup/platform";
441	
442	/**
443	 * Stamped into the vzdump notes of platform archives (see `--notes-template` in
444	 * scripts/backup-vms.sh). Customer retention must never delete an archive whose
445	 * notes contain this string.
446	 */
447	export const PLATFORM_BACKUP_MARKER = "NXEON-PLATFORM-BACKUP";
448	
449	/**
450	 * One volid per line. Maintained by scripts/backup-vms.sh; also seeded with any
451	 * pre-existing platform archives that were written into the shared storage before
452	 * the dumpdir split. Anything listed here is undeletable through this module.
453	 */
454	const PROTECTED_REGISTRY = `${PLATFORM_BACKUP_DIR}/PROTECTED-VOLIDS`;
455	
456	/**
457	 * Read the protection registry.
458	 *
459	 * Returns `null` when the registry exists but could not be read. Callers MUST
460	 * treat `null` as "protection state unknown" and refuse to delete: a transient
461	 * EIO on this file must not be the thing that lets a customer's prune wipe the
462	 * platform's recovery set. A registry that simply does not exist yet (fresh
463	 * install, platform job has never run) is a legitimate empty set — layer 1 means
464	 * there is nothing in the shared storage to protect in that case anyway.
465	 */
466	async function protectedVolids(): Promise<Set<string> | null> {
467	  const { readFile } = await import("node:fs/promises");
468	  try {
469	    const raw = await readFile(PROTECTED_REGISTRY, "utf8");
470	    return new Set(
471	      raw.split("\n").map((l) => l.trim()).filter((l) => l.length > 0 && !l.startsWith("#"))
472	    );
473	  } catch (e: any) {
474	    if (e?.code === "ENOENT") return new Set();
475	    console.error(`[proxmox] protection registry ${PROTECTED_REGISTRY} unreadable — refusing to prune`, e);
476	    return null;
477	  }
478	}
479	
480	/** Shape of one entry in `/nodes/<node>/storage/<sid>/content`. */
481	export type StorageBackupEntry = {
482	  volid?: string;
483	  vmid?: number;
484	  ctime?: number;
485	  size?: number;
486	  notes?: string;
487	  protected?: boolean | number;
488	};
489	
490	/**
491	 * Is this archive one of the platform's own (i.e. never customer-prunable)?
492	 * Any single signal is enough — they are deliberately redundant.
493	 */
494	export function isPlatformArchive(b: StorageBackupEntry, registry: Set<string>): boolean {
495	  if (b.protected) return true;
496	  if (typeof b.notes === "string" && b.notes.includes(PLATFORM_BACKUP_MARKER)) return true;
497	  if (typeof b.volid === "string" && registry.has(b.volid)) return true;
498	  return false;
499	}
500	
501	/**
502	 * Delete one backup archive by its Proxmox volume id. `client` = the node's pve client.
503	 *
504	 * This is the ONLY storage-content DELETE in the codebase, so it is where the
505	 * "a customer can never delete a platform archive" invariant is enforced rather
506	 * than merely intended. It re-checks protection against the live hypervisor for
507	 * the exact volid being deleted — a caller that passed a stale or hand-crafted
508	 * volid cannot slip past it. Every uncertain outcome throws.
509	 */
510	export async function deleteBackup(client: any, volid: string): Promise<void> {
511	  // Only `<storage>:backup/<basename>` volids are deletable here. Rejecting
512	  // anything else keeps a malformed or path-traversing volid from ever reaching
513	  // the API, and keeps this function honest about what it operates on.
514	  const m = /^([A-Za-z0-9._-]+):backup\/([^/]+)$/.exec(volid);
515	  if (!m) throw new Error(`refusing to delete: '${volid}' is not a <storage>:backup/<file> volid`);
516	
517	  const registry = await protectedVolids();
518	  if (registry === null) {
519	    throw new Error(`refusing to delete ${volid}: platform protection registry unreadable`);
520	  }
521	  if (registry.has(volid)) {
522	    throw new Error(`refusing to delete ${volid}: listed in the platform protection registry`);
523	  }
524	
525	  // Ask the hypervisor about this exact volume. `notes` and `protected` are both
526	  // returned by the content-info endpoint (PVE::API2::Storage::Content). A failure
527	  // here means we do not know whether this is a platform archive, so we stop.
528	  let info: any;
529	  try {
530	    info = await client.get(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
531	  } catch (e) {
532	    throw new Error(`refusing to delete ${volid}: could not read its attributes (${e})`);
533	  }
534	  if (isPlatformArchive({ volid, notes: info?.notes, protected: info?.protected }, registry)) {
535	    throw new Error(`refusing to delete ${volid}: it is a platform (host-level) backup`);
536	  }
537	
538	  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
539	}
540	
541	/**
542	 * Retention for ONE CUSTOMER SERVER: keep only the newest `keep` archives that
543	 * belong to that customer, deleting the older ones (best-effort per file, oldest
544	 * first). Runs after every successful customer backup, and from the standalone
545	 * sweep in worker/backup-schedule.ts. Returns how many were deleted.
546	 *
547	 * Platform archives are excluded from the delete set AND from the retention
548	 * count. Counting them would be its own bug: with keep = 2, three platform
549	 * archives of a vmid would make every customer archive "older than the newest
550	 * two" and delete all of the customer's backups instead.
551	 */
552	export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
553	  const registry = await protectedVolids();
554	  if (registry === null) {
555	    // Fail closed: no retention this pass. Archives accumulating for one cycle is
556	    // recoverable; deleting the platform's only copy of a VM is not.
557	    console.error(`[proxmox] pruneBackups: protection state unknown, skipping prune for vmid ${vmid}`);
558	    return 0;
559	  }
560	
561	  const content: StorageBackupEntry[] = await client.get(
562	    `/nodes/${client.node}/storage/backup/content`,
563	    { content: "backup" }
564	  );
565	  const forVmid = content.filter((b) => b.vmid === vmid && typeof b.volid === "string");
566	  const shielded = forVmid.filter((b) => isPlatformArchive(b, registry));
567	  const mine = forVmid
568	    .filter((b) => !isPlatformArchive(b, registry))
569	    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
570	
571	  if (shielded.length > 0) {
572	    console.log(
573	      `[proxmox] pruneBackups: vmid ${vmid} — ${shielded.length} platform archive(s) excluded from retention`
574	    );
575	  }
576	
577	  const toDelete = mine.slice(Math.max(0, keep));
578	  let deleted = 0;
579	  for (const b of toDelete) {
580	    try {
581	      await deleteBackup(client, b.volid!);
582	      deleted++;
583	    } catch (e) {
584	      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
585	    }
586	  }
587	  return deleted;
588	}
