4	/**
5	 * Scheduled-backup sweep.
6	 *
7	 * `scheduledBackupSweep` finds RUNNING servers that opted into recurring backups
8	 * (`autoBackup=true`) whose last automatic backup is older than their configured
9	 * cadence (or which have never had one), and enqueues a BACKUP_CREATE job for
10	 * each — de-duping on any in-flight job so it's safe to call on a timer.
11	 *
12	 * NOTE: `worker/index.ts` owns the job loop; it already knows how to run
13	 * BACKUP_CREATE jobs. Wire this sweep into the main loop on a timer, e.g.:
14	 *
15	 *   import { scheduledBackupSweep } from "./backup-schedule";
16	 *   if (Date.now() - lastBackupSweep > 15 * 60_000) {
17	 *     lastBackupSweep = Date.now();
18	 *     try { await scheduledBackupSweep(); } catch (e) { console.error(e); }
19	 *   }
20	 */
21	export async function scheduledBackupSweep(): Promise<void> {
22	  if (SANDBOX) return; // no real backups run in the sandbox
23	  const now = Date.now();
24	
25	  const candidates = await db.server.findMany({
26	    where: {
27	      status: "RUNNING",
28	      autoBackup: true,
29	      backupIntervalHours: { not: null },
30	    },
31	    select: {
32	      id: true,
33	      hostname: true,
34	      backupIntervalHours: true,
35	      lastAutoBackup: true,
36	    },
37	  });
38	  if (candidates.length === 0) return;
39	
40	  let enqueued = 0;
41	  for (const s of candidates) {
42	    const intervalMs = (s.backupIntervalHours ?? 0) * 60 * 60_000;
43	    if (intervalMs <= 0) continue;
44	
45	    // Due if it has never run, or the cadence has elapsed since the last one.
46	    const dueAt = s.lastAutoBackup ? s.lastAutoBackup.getTime() + intervalMs : 0;
47	    if (now < dueAt) continue;
48	
49	    // Respect the one-in-flight-job-per-server invariant.
50	    const inflight = await db.job.count({
51	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
52	    });
53	    if (inflight > 0) continue;
54	
55	    await db.job.create({ data: { type: "BACKUP_CREATE", serverId: s.id } });
56	    // Mark the schedule as satisfied now so a slow backup / a second sweep pass
57	    // doesn't pile up duplicate jobs; the timestamp anchors the next window.
58	    await db.server.update({
59	      where: { id: s.id },
60	      data: { lastAutoBackup: new Date() },
61	    });
62	    enqueued++;
63	  }
64	
65	  if (enqueued > 0) console.log(`[backup-schedule] sweep enqueued ${enqueued} backup job(s)`);
66	}
