15	/**
16	 * Block storage volume handlers (add-on disks attached to a VPS).
17	 *
18	 * `worker/index.ts` owns the job loop and the `handlers` map; wire these in there:
19	 *   VOLUME_CREATE: volumeCreate,
20	 *   VOLUME_ATTACH: volumeAttach,
21	 *   VOLUME_DETACH: volumeDetach,
22	 *   VOLUME_DELETE: volumeDelete,
23	 *
24	 * Ownership + validation are enforced at enqueue time (lib/actions-volumes.ts),
25	 * so these handlers trust `payload.volumeId` / `payload.targetServerId`.
26	 *
27	 * A volume's underlying Proxmox disk only exists once it has been attached at
28	 * least once. `Volume.diskName` stores the STABLE Proxmox volume id of that disk
29	 * (e.g. "vmdata:vm-101-disk-1") — not a slot — because the slot/unused index
30	 * changes across detach/re-attach; we always re-scan the VM config to find the
31	 * disk's current key (scsiN while attached, unusedN while detached).
32	 *
33	 * ─── THREE THINGS THIS FILE IS RESPONSIBLE FOR ──────────────────────────────
34	 *
35	 * 1. PORTABILITY (a volume is sold as a portable disk, not a welded one).
36	 *    A Proxmox disk is OWNED by a vmid (`vm-<vmid>-disk-N`), so moving a volume
37	 *    to another server is not a DB edit — the disk has to be reassigned to the
38	 *    other VM (`move_disk` + `target-vmid`, which RENAMES the volume). See
39	 *    `reassignDiskToServer`. PVE requires both VMs on the same node, so a
40	 *    cross-node move is refused up front instead of half-done.
41	 *
42	 * 2. GUEST PREPARATION (format on first use, mount on every use).
43	 *    Nothing used to format or mount a volume: attach hot-plugged a raw disk and
44	 *    the notification told the customer to do it themselves. That is also why
45	 *    `Volume.inUse` was never knowable. `prepareGuestVolume` now does it — and is
46	 *    written to REFUSE on any ambiguity rather than risk a customer's bytes.
47	 *
48	 * 3. SAFE DETACH (never hot-unplug a live filesystem).
49	 *    A detach used to be an unconditional SCSI unplug with no sync and no
50	 *    unmount: a volume mounted at /var/lib/mysql lost its device mid-write →
51	 *    journal abort / InnoDB corruption. `releaseGuestVolume` unmounts first and
52	 *    REFUSES when the filesystem is still in use, unless the customer has given
53	 *    an explicit informed override (`payload.ackInUse`).
54	 *
55	 * ─── PROXMOX CONFIG WRITES ARE ASYNCHRONOUS ─────────────────────────────────
56	 * A config POST returns before the config file reflects it, so an immediate GET
57	 * can hand back the pre-write view. Every read-after-write in this file goes
58	 * through `waitForConfig` — that race is exactly how volumes ended up with a
59	 * null `diskName` in production.
60	 */
61	
62	async function loadVolume(job: Job) {
63	  const payload = (job.payload ?? {}) as { volumeId?: string };
64	  if (!payload.volumeId) throw new Error("volume job: missing volumeId");
65	  const volume = await db.volume.findUnique({
66	    where: { id: payload.volumeId },
67	    // `dedicatedIp` is needed to open an SSH session to the guest (lib/sftp
68	    // connectionTarget: dedicated IP:22, else PUBLIC_IP:sshPort).
69	    include: { server: { include: { node: true, dedicatedIp: true } } },
70	  });
71	  if (!volume) throw new Error(`Volume ${payload.volumeId} not found`);
72	  return volume;
73	}
