161	/** First free scsiN slot (scsi0 is the OS disk). Proxmox supports scsi0..scsi30. */
162	function freeScsiSlot(config: Record<string, any>): string {
163	  for (let i = 1; i <= 30; i++) {
164	    if (config[`scsi${i}`] === undefined) return `scsi${i}`;
165	  }
166	  throw new Error("no free scsi slot available on this VM");
167	}
168	
169	/** Find the config key (scsiN / unusedN / …) that currently references `volid`. */
170	function keyForVolid(config: Record<string, any>, volid: string): string | null {
171	  for (const [k, v] of Object.entries(config)) {
172	    if (typeof v === "string" && volidOf(v) === volid) return k;
173	  }
174	  return null;
175	}
