201	/**
202	 * Is the VM actually running right now?
203	 *
204	 * `Server.status` is NOT good enough for this decision: a row can say STOPPED or
205	 * ERROR while the VM is up (and vice versa), and getting it wrong here means
206	 * hot-unplugging a mounted filesystem. Proxmox is the ground truth; "unknown" is
207	 * reported honestly so the caller can refuse instead of assuming.
208	 */
209	async function vmRunState(conn: any, vmid: number): Promise<"running" | "stopped" | "unknown"> {
210	  try {
211	    const s = await conn.vmStatus(vmid);
212	    const st = String(s?.status ?? "");
213	    if (st === "running") return "running";
214	    if (st) return "stopped";
215	  } catch (e) {
216	    console.error(`[volumes] could not read run state of VM ${vmid}`, e);
217	  }
218	  return "unknown";
219	}
220	
221	// ===========================================================================
222	// GUEST SIDE — detect / format / mount / unmount
223	// ===========================================================================
224	/**
225	 * Everything below runs inside the customer's VM over SSH, and every command is
226	 * built the way lib/ssh-exec.ts demands: values are validated against a
227	 * shell-inert allowlist FIRST (we reject, never sanitize) and quoted second.
228	 *
229	 * The formatting decision is the most dangerous operation in this file, so it is
230	 * deliberately gated by five INDEPENDENT layers, and any one of them failing (or
231	 * being merely unclear) means we mount nothing and format nothing:
232	 *
233	 *   1. IDENTITY — the device must be one that appeared in the guest between a
234	 *      snapshot taken BEFORE the hot-plug and a poll taken after it, and exactly
235	 *      one such device may appear. We never guess "probably /dev/sdb".
236	 *   2. SIZE — that device's size must match the volume's nominal size.
237	 *   3. HISTORY — the Volume row must never have carried a filesystem
238	 *      (`fsType`/`mountPath`/`inUse` all unset). If the row says it was
239	 *      formatted but the disk looks blank, that contradiction means we may be
240	 *      looking at the wrong device: refuse and report, touch nothing.
241	 *   4. SIGNATURES — `blkid`, `wipefs -n`, children, holders and mountpoints must
242	 *      all come back empty, AND three separate 1–4 MiB windows (start, middle,
243	 *      end) must read as pure zeros. Every filesystem/partition table/LVM/LUKS/
244	 *      md-raid layout writes a header inside those windows, so "no signature and
245	 *      zeros at both ends" is as close to proof-of-blank as a disk allows.
246	 *   5. mke2fs ITSELF — `mkfs.ext4` is invoked with a SINGLE `-F`. That waives
247	 *      only the "this is a whole device, not a partition" objection; a single
248	 *      `-F` still makes mke2fs refuse a device that is mounted or otherwise in
249	 *      use by the kernel (two are required to override that), so the kernel gets
250	 *      the last veto after all our own checks.
251	 */
252	
253	const GiB = 1024 ** 3;
254	/** A bare kernel block-device name we are willing to interpolate: "sdb", "vdc". */
255	const DEV_NAME_RE = /^[a-z][a-z0-9]{1,31}$/;
256	const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
257	/** Absolute mount path we either generate or read back from the guest. */
258	const MOUNT_PATH_RE = /^\/[A-Za-z0-9._/-]{1,120}$/;
259	/** Filesystems we are willing to mount unattended. */
260	const MOUNTABLE_FS = new Set(["ext2", "ext3", "ext4", "xfs", "btrfs"]);
261	/** What a blank volume gets formatted with. */
262	const VOLUME_FS = "ext4";
263	
264	/** Strip control characters and clamp — everything read back from the guest. */
265	function clean(s: unknown, max: number): string {
266	  return String(s ?? "")
267	    .replace(/[\x00-\x1f\x7f]/g, " ")
268	    .trim()
269	    .slice(0, max);
270	}
271	
272	/**
273	 * Run one guest command, turning transport failures into an empty result instead
274	 * of an exception: every caller treats "no output" as "unclear → do not touch",
275	 * so a timeout can never be mistaken for a green light (nor fail an attach that
276	 * has already been paid for and hot-plugged).
277	 */
278	async function sh(
279	  conn: Client,
280	  cmd: string,
281	  timeoutMs: number = QUICK_TIMEOUT_MS
282	): Promise<{ code: number | null; stdout: string; stderr: string }> {
283	  try {
284	    return await exec(conn, cmd, timeoutMs);
285	  } catch (e: any) {
286	    return { code: null, stdout: "", stderr: String(e?.message ?? e) };
287	  }
288	}
289	
290	/** Pull `KEY=value` out of a probe's stdout. */
291	function kv(out: string, key: string): string {
292	  return clean(new RegExp(`^${key}=(.*)$`, "m").exec(out ?? "")?.[1] ?? "", 255);
293	}
294	
295	type GuestDisk = { name: string; type: string; sizeBytes: number; fstype: string; mount: string; pkname: string };
296	
297	function parseLsblk(out: string): GuestDisk[] {
298	  const rows: GuestDisk[] = [];
299	  for (const line of (out ?? "").split("\n")) {
300	    if (!line.trim()) continue;
301	    const map: Record<string, string> = {};
302	    for (const m of line.matchAll(/([A-Z]+)="([^"]*)"/g)) map[m[1]] = m[2];
303	    if (!map.NAME) continue;
304	    rows.push({
305	      name: clean(map.NAME, 64),
306	      type: clean(map.TYPE ?? "", 32),
307	      sizeBytes: Number(map.SIZE) || 0,
308	      fstype: clean(map.FSTYPE ?? "", 32),
309	      mount: clean(map.MOUNTPOINT ?? "", 200),
310	      pkname: clean(map.PKNAME ?? "", 64),
311	    });
312	  }
313	  return rows;
314	}
315	
316	/** Every block device the guest can see right now, or null if it could not be read. */
317	async function guestBlockDevices(conn: Client): Promise<GuestDisk[] | null> {
318	  const r = await sh(conn, `lsblk -b -P -o NAME,TYPE,SIZE,FSTYPE,MOUNTPOINT,PKNAME 2>/dev/null`);
319	  const rows = parseLsblk(r.stdout);
320	  return rows.length ? rows : null;
321	}
322	
323	/**
324	 * Names of the whole disks that carry (or stack under) the root filesystem.
325	 * Nothing in that tree is ever a candidate, however it is stacked (partition,
326	 * LVM, dm-crypt) — walking PKNAME keeps an LVM root from ever looking "blank".
327	 */
328	async function rootDiskNames(conn: Client, rows: GuestDisk[]): Promise<Set<string>> {
329	  const byName = new Map(rows.map((r) => [r.name, r]));
330	  const topOf = (name: string): string => {
331	    let cur = name;
332	    for (let i = 0; i < 8; i++) {
333	      const row = byName.get(cur);
334	      if (!row?.pkname || row.pkname === cur) break;
335	      cur = row.pkname;
336	    }
337	    return cur;
338	  };
339	  const out = new Set<string>();
340	  const r = await sh(conn, `findmnt -nro SOURCE / 2>/dev/null | head -n1`);
341	  const src = clean(r.stdout, 128);
342	  if (src.startsWith("/dev/")) {
343	    out.add(topOf(src.slice(src.lastIndexOf("/") + 1)));
344	    const pk = await sh(conn, `lsblk -no PKNAME ${shellQuote(src)} 2>/dev/null | head -n1`);
345	    const parent = clean(pk.stdout, 64);
346	    if (parent) out.add(topOf(parent));
347	  }
348	  return out;
349	}
350	
351	/** Whole-disk names visible in the guest (excluding the root disk's tree). */
352	async function guestDiskNames(conn: Client): Promise<Set<string> | null> {
353	  const rows = await guestBlockDevices(conn);
354	  if (!rows) return null;
355	  const roots = await rootDiskNames(conn, rows);
356	  return new Set(rows.filter((d) => d.type === "disk" && !roots.has(d.name)).map((d) => d.name));
357	}
358	
359	type DeviceProbe = {
360	  ok: boolean;
361	  sizeBytes: number;
362	  fsType: string;
363	  ptType: string;
364	  uuid: string;
365	  mount: string;
366	  /** True only when EVERY blankness test came back negative. */
367	  blank: boolean;
368	  /** Human-readable list of the signs of data we found (empty when blank). */
369	  evidence: string[];
370	};
371	
372	/**
373	 * READ-ONLY interrogation of one whole disk, in a single round trip.
374	 *
375	 * `blkid -p` probes the device itself rather than the (possibly stale) cache, and
376	 * the three `dd` windows catch layouts libblkid does not know: a filesystem, a
377	 * partition table, an LVM PV label, a LUKS header, an md-raid superblock (1.0
378	 * lives at the END of the device — hence the tail window) or a swap area all put
379	 * bytes inside them. Reading is the only thing this function does.
380	 */
381	async function probeDevice(conn: Client, name: string): Promise<DeviceProbe> {
382	  const fail: DeviceProbe = { ok: false, sizeBytes: 0, fsType: "", ptType: "", uuid: "", mount: "", blank: false, evidence: ["the disk could not be interrogated"] };
383	  if (!DEV_NAME_RE.test(name)) return fail;
384	  const dev = `/dev/${name}`;
385	  const q = shellQuote(dev);
386	  const probe = [
387	    `SZ=$(blockdev --getsize64 ${q} 2>/dev/null || echo 0)`,
388	    `echo "SIZE=$SZ"`,
389	    `echo "FSTYPE=$(blkid -p -s TYPE -o value ${q} 2>/dev/null)"`,
390	    `echo "PTTYPE=$(blkid -p -s PTTYPE -o value ${q} 2>/dev/null)"`,
391	    `echo "USAGE=$(blkid -p -s USAGE -o value ${q} 2>/dev/null)"`,
392	    `echo "UUID=$(blkid -s UUID -o value ${q} 2>/dev/null)"`,
393	    `echo "MOUNT=$(findmnt -nro TARGET -S ${q} 2>/dev/null | head -n1)"`,
394	    `echo "HOLDERS=$(ls -A /sys/block/${name}/holders 2>/dev/null | tr '\\n' ' ')"`,
395	    `echo "CHILDREN=$(lsblk -no NAME ${q} 2>/dev/null | tail -n +2 | tr -d ' ' | tr '\\n' ' ')"`,
396	    `if command -v wipefs >/dev/null 2>&1; then echo "WIPEFS=$(wipefs -n ${q} 2>/dev/null | wc -l)"; else echo "WIPEFS=na"; fi`,
397	    // Three zero-windows: first 4 MiB, 1 MiB at the midpoint, last 1 MiB.
398	    `nz() { dd if=${q} bs=1048576 skip="$1" count="$2" iflag=skip_bytes,count_bytes 2>/dev/null | tr -d '\\000' | wc -c; }`,
399	    `[ "$SZ" -gt 8388608 ] 2>/dev/null && { echo "ZHEAD=$(nz 0 4194304)"; echo "ZMID=$(nz $((SZ/2)) 1048576)"; echo "ZTAIL=$(nz $((SZ-1048576)) 1048576)"; }`,
400	    `echo "PROBE=OK"`,
401	  ].join("; ");
402	
403	  const r = await sh(conn, probe, SETUP_TIMEOUT_MS);
404	  if (kv(r.stdout, "PROBE") !== "OK") return fail;
405	
406	  const sizeBytes = Number(kv(r.stdout, "SIZE")) || 0;
407	  const fsType = kv(r.stdout, "FSTYPE").toLowerCase();
408	  const ptType = kv(r.stdout, "PTTYPE").toLowerCase();
409	  const usage = kv(r.stdout, "USAGE").toLowerCase();
410	  const uuid = kv(r.stdout, "UUID");
411	  const mount = kv(r.stdout, "MOUNT");
412	  const holders = kv(r.stdout, "HOLDERS");
413	  const children = kv(r.stdout, "CHILDREN");
414	  const wipefs = kv(r.stdout, "WIPEFS");
415	  const zhead = kv(r.stdout, "ZHEAD");
416	  const zmid = kv(r.stdout, "ZMID");
417	  const ztail = kv(r.stdout, "ZTAIL");
418	
419	  const evidence: string[] = [];
420	  if (fsType) evidence.push(`a ${fsType} filesystem`);
421	  if (ptType) evidence.push(`a ${ptType} partition table`);
422	  if (usage && !fsType && !ptType) evidence.push(`a ${usage} signature`);
423	  if (uuid) evidence.push(`filesystem UUID ${uuid}`);
424	  if (mount) evidence.push(`it is mounted at ${mount}`);
425	  if (holders) evidence.push(`kernel holders (${holders})`);
426	  if (children) evidence.push(`child devices (${children})`);
427	  // `wipefs -n` prints nothing at all when it finds no magic; any line is a hit.
428	  if (wipefs !== "na" && Number(wipefs) > 0) evidence.push("on-disk signatures reported by wipefs");
429	  // A missing/short size, or zero-windows we could not read, is ambiguity — and
430	  // ambiguity is treated exactly like data.
431	  if (sizeBytes <= 8 * 1024 * 1024) evidence.push("its size could not be read");
432	  else if (zhead !== "0" || zmid !== "0" || ztail !== "0") {
433	    evidence.push(
434	      zhead === "" || zmid === "" || ztail === ""
435	        ? "the raw start/middle/end of the disk could not be read back"
436	        : "non-zero bytes at the start, middle or end of the disk"
437	    );
438	  }
439	
440	  return { ok: true, sizeBytes, fsType, ptType, uuid, mount, blank: evidence.length === 0, evidence };
441	}
442	
443	/** Does `sizeBytes` plausibly belong to a `sizeGB` volume? */
444	function sizeMatches(sizeBytes: number, sizeGB: number): boolean {
445	  const expected = Math.max(1, Math.round(sizeGB)) * GiB;
446	  // Storage back-ends round up to an extent / volblocksize, so allow a little
447	  // slack — but not enough to confuse a volume with a differently-sized disk.
448	  const slack = Math.max(64 * 1024 * 1024, expected * 0.03);
449	  return sizeBytes >= expected - slack && sizeBytes <= expected + slack;
450	}
451	
452	/** The default, stable mount point for a volume. Stable across re-attaches. */
453	function defaultMountPath(volumeId: string): string | null {
454	  const slug = String(volumeId ?? "").toLowerCase().replace(/[^a-z0-9]/g, "");
455	  if (slug.length < 8) return null;
456	  const path = `/mnt/nxeon-vol-${slug}`;
457	  return MOUNT_PATH_RE.test(path) ? path : null;
458	}
459	
460	/**
461	 * Give the guest a chance to notice a freshly hot-plugged SCSI disk, then return
462	 * the ONE device that appeared since `before`.
463	 *
464	 * Identity by set-difference (not by name, size or slot arithmetic) is what makes
465	 * the rest of this safe: the device we go on to touch is, by construction, the one
466	 * that appeared when we plugged this volume in. Zero or several new devices means
467	 * we cannot say which disk is the customer's — so we say so and stop.
468	 */
469	async function findAttachedDevice(
470	  conn: Client,
471	  before: Set<string>,
472	  sizeGB: number
473	): Promise<{ name: string } | { error: string }> {
474	  // Writing "- - -" to a SCSI host's scan node only asks the kernel to re-probe.
475	  await sh(conn, `for h in /sys/class/scsi_host/host*/scan; do echo '- - -' > "$h" 2>/dev/null; done; udevadm settle 2>/dev/null; true`);
476	
477	  let appeared: GuestDisk[] = [];
478	  for (let i = 0; i < 12; i++) {
479	    const rows = await guestBlockDevices(conn);
480	    if (rows) {
481	      const roots = await rootDiskNames(conn, rows);
482	      appeared = rows.filter((d) => d.type === "disk" && !roots.has(d.name) && !before.has(d.name));
483	      if (appeared.length) break;
484	    }
485	    await new Promise((r) => setTimeout(r, 2500));
486	  }
487	
488	  if (appeared.length === 0) {
489	    return { error: "the server did not report a new disk after the attach (a reboot usually makes it appear)" };
490	  }
491	  if (appeared.length > 1) {
492	    return { error: `${appeared.length} new disks appeared at once, so we cannot tell which one is this volume` };
493	  }
494	  const dev = appeared[0];
495	  if (!DEV_NAME_RE.test(dev.name)) {
496	    return { error: `the new disk has an unexpected device name (${dev.name.slice(0, 20)})` };
497	  }
498	  if (!sizeMatches(dev.sizeBytes, sizeGB)) {
499	    return {
500	      error:
501	        `the new disk is ${Math.round(dev.sizeBytes / GiB)} GB but this volume is ${sizeGB} GB — ` +
502	        `refusing to touch a disk we cannot positively identify`,
503	    };
504	  }
505	  return { name: dev.name };
506	}
507	
508	/**
509	 * Persist an ALREADY-FORMATTED filesystem: an /etc/fstab entry BY UUID (never by
510	 * /dev/sdX — a volume can come back as a different letter, and then fstab mounts
511	 * the wrong disk) with `nofail`, then mount it.
512	 *
513	 * `nofail` is not optional. A volume can be detached, moved to another server or
514	 * simply fail to appear; without `nofail` systemd holds local-fs.target and the
515	 * customer's server does not finish booting. An unmounted disk is a support
516	 * ticket, a server that will not boot is an outage.
517	 *
518	 * Idempotent: the grep guard and the `mountpoint -q` short-circuit make a re-run
519	 * a no-op. NEVER formats — that decision belongs to the caller alone.
520	 */
521	async function mountVolumeFs(
522	  conn: Client,
523	  devName: string,
524	  mountPath: string,
525	  fsType: string
526	): Promise<{ ok: true; uuid: string } | { ok: false; error: string }> {
527	  if (!DEV_NAME_RE.test(devName)) return { ok: false, error: "device name failed validation" };
528	  if (!MOUNT_PATH_RE.test(mountPath) || mountPath.includes("..") || mountPath.includes("//")) {
529	    return { ok: false, error: `unsupported mount path ${mountPath.slice(0, 40)}` };
530	  }
531	  if (!MOUNTABLE_FS.has(fsType)) return { ok: false, error: `unsupported filesystem ${fsType.slice(0, 20)}` };
532	
533	  const dev = shellQuote(`/dev/${devName}`);
534	  const path = shellQuote(mountPath);
535	
536	  // udev may still be settling right after a mkfs; give the UUID two chances.
537	  let uuid = "";
538	  for (let i = 0; i < 2 && !UUID_RE.test(uuid); i++) {
539	    if (i) await sh(conn, `udevadm settle 2>/dev/null; true`);
540	    uuid = clean((await sh(conn, `blkid -s UUID -o value ${dev} 2>/dev/null`)).stdout, 64);
541	  }
542	  if (!UUID_RE.test(uuid)) return { ok: false, error: "could not read a filesystem UUID back" };
543	
544	  // Refuse to stack our mount on top of somebody else's filesystem.
545	  const occupied = await sh(conn, `findmnt -nro SOURCE --mountpoint ${path} 2>/dev/null | head -n1`);
546	  const occupiedBy = clean(occupied.stdout, 128);
547	  if (occupiedBy && occupiedBy !== `/dev/${devName}`) {
548	    return { ok: false, error: `${mountPath} is already in use by ${occupiedBy}` };
549	  }
550	
551	  await sh(conn, `mkdir -p ${path}`);
552	  await sh(
553	    conn,
554	    `grep -q "UUID=${uuid} " /etc/fstab || printf 'UUID=%s %s %s defaults,nofail 0 2\\n' '${uuid}' ${path} ${shellQuote(fsType)} >> /etc/fstab`
555	  );
556	  await sh(conn, `mountpoint -q ${path} || mount ${path} 2>&1 || mount ${dev} ${path} 2>&1`, SETUP_TIMEOUT_MS);
557	  const live = await sh(conn, `mountpoint -q ${path} && echo MOUNTED`);
558	  if (!clean(live.stdout, 32).includes("MOUNTED")) {
559	    return { ok: false, error: `mounting ${mountPath} failed` };
560	  }
561	  return { ok: true, uuid };
562	}
