564	/** Where should this volume be mounted? Never invents a path over an existing layout. */
565	async function resolveMountPath(
566	  conn: Client,
567	  volume: { id: string; mountPath: string | null },
568	  uuid: string
569	): Promise<string | null> {
570	  // 1) An fstab entry for THIS filesystem wins: it is where the guest already
571	  //    expects the disk, and the migration engine bind-mounts Docker's stores out
572	  //    of that directory. Mounting somewhere else would leave those binds dangling.
573	  if (UUID_RE.test(uuid)) {
574	    const r = await sh(conn, `awk -v u="UUID=${uuid}" '$1==u {print $2; exit}' /etc/fstab 2>/dev/null`);
575	    const fromFstab = clean(r.stdout, 200);
576	    if (MOUNT_PATH_RE.test(fromFstab)) return fromFstab;
577	  }
578	  // 2) Then the path we recorded last time (kept across a detach for the same reason).
579	  if (volume.mountPath && MOUNT_PATH_RE.test(volume.mountPath)) return volume.mountPath;
580	  // 3) Otherwise our own stable path.
581	  return defaultMountPath(volume.id);
582	}
