833	/**
834	 * Drop the fstab line we own (matched on the filesystem UUID, so nothing else can
835	 * match it). Deliberately leaves any bind-mount lines the migration engine wrote
836	 * alone: those are its configuration, not ours, and every entry it writes also
837	 * carries `nofail`, so a missing source directory cannot break the boot.
838	 */
839	async function removeFstabEntry(conn: Client, uuid: string): Promise<void> {
840	  if (!UUID_RE.test(uuid)) return;
841	  await sh(conn, `sed -i "\\|^UUID=${uuid}[[:space:]]|d" /etc/fstab 2>/dev/null; true`);
842	}
