887	/**
888	 * Move an existing disk from the VM that currently owns it to `target`.
889	 *
890	 * A Proxmox disk is named after its owner (`vm-<vmid>-disk-N`), so "the same
891	 * volume on a different server" is a reassignment, not a config copy:
892	 * POST .../move_disk with `target-vmid` renames the volume on the storage and
893	 * moves the config entry across in one locked operation. PVE refuses to do it
894	 * across nodes, so the caller checks that first.
895	 *
896	 * Returns the slot it landed in and its NEW volid — the old `Volume.diskName` is
897	 * dead the moment the rename succeeds.
898	 */
899	async function reassignDiskToServer(
900	  conn: any,
901	  volume: { diskName: string | null; name: string },
902	  sourceVmid: number,
903	  sourceRunning: boolean,
904	  target: { vmid: number; hostname: string }
905	): Promise<{ slot: string; volid: string }> {
906	  const volid = String(volume.diskName);
907	  let sourceConfig = (await conn.get(`/nodes/${conn.node}/qemu/${sourceVmid}/config`)) as Record<string, any>;
908	  let key = keyForVolid(sourceConfig, volid);
909	  if (!key) {
910	    // The disk is not on the VM that is supposed to own it. Creating a fresh one
911	    // would silently hand the customer an empty disk and orphan the real data,
912	    // so stop instead.
913	    throw new Error(
914	      `volume "${volume.name}" is recorded as ${volid} on VM ${sourceVmid}, but that disk is not in the VM's config. ` +
915	        `Refusing to guess — nothing was changed.`
916	    );
917	  }
918	  if (key.startsWith("scsi")) {
919	    // The DB says detached but the disk is still plugged in (a detach that never
920	    // finished). Unplugging a live disk from a RUNNING VM is the corruption we
921	    // refuse elsewhere, so refuse it here too.
922	    if (sourceRunning) {
923	      throw new Error(
924	        `volume "${volume.name}" is still plugged into VM ${sourceVmid} as ${key}. Detach it from that server first.`
925	      );
926	    }
927	    await conn.post(`/nodes/${conn.node}/qemu/${sourceVmid}/config`, { delete: key });
928	    sourceConfig = await waitForConfig(conn, sourceVmid, (c) => {
929	      const k = keyForVolid(c, volid);
930	      return !!k && k.startsWith("unused");
931	    });
932	    key = keyForVolid(sourceConfig, volid);
933	    if (!key || key.startsWith("scsi")) {
934	      throw new Error(`could not detach ${volid} from VM ${sourceVmid} before moving it`);
935	    }
936	  }
937	
938	  const targetConfig = (await conn.get(`/nodes/${conn.node}/qemu/${target.vmid}/config`)) as Record<string, any>;
939	  const slot = freeScsiSlot(targetConfig);
940	
941	  const upid = await conn.post(`/nodes/${conn.node}/qemu/${sourceVmid}/move_disk`, {
942	    disk: key,
943	    "target-vmid": target.vmid,
944	    "target-disk": slot,
945	  });
946	  if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
947	
948	  // The volume was RENAMED to vm-<target>-disk-N, so read the new volid back —
949	  // polling, because the config write lands after the API call returns.
950	  const after = await waitForConfig(conn, target.vmid, (c) => isRealVolid(volidOf(c[slot])));
951	  const newVolid = volidOf(after[slot]);
952	  if (!isRealVolid(newVolid)) {
953	    throw new Error(
954	      `the disk move to ${target.hostname} did not show up in the VM config; not recording a guess. ` +
955	        `Check VM ${target.vmid} on the hypervisor before retrying.`
956	    );
957	  }
958	  return { slot, volid: newVolid };
959	}
