1257	/**
1258	 * VOLUME_DELETE — detach (if attached) then permanently destroy the underlying
1259	 * disk, and remove the Volume row.
1260	 */
1261	export async function volumeDelete(job: Job): Promise<void> {
1262	  const volume = await loadVolume(job);
1263	  const server = volume.server;
1264	
1265	  if (SANDBOX) {
1266	    await db.volume.delete({ where: { id: volume.id } });
1267	    await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
1268	    return;
1269	  }
1270	
1271	  // The customer has accepted losing this volume's data, so a busy filesystem is
1272	  // NOT a reason to refuse here — but unmounting first still matters: yanking the
1273	  // device from under an open file wedges the processes using it and can take
1274	  // unrelated services on the same server down with it. Best effort only.
1275	  if (server?.vmid && server.status === "RUNNING" && (volume.inUse || volume.mountPath)) {
1276	    await releaseGuestVolume(server, volume, true).catch(() => undefined);
1277	  }
1278	
1279	  if (server?.vmid && volume.diskName) {
1280	    const { conn } = await nodeFor(server);
1281	    try {
1282	      let config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
1283	      let key = keyForVolid(config, volume.diskName);
1284	
1285	      // If still mounted, detach to an "unused" entry first.
1286	      if (key && key.startsWith("scsi")) {
1287	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
1288	        config = await waitForConfig(conn, server.vmid, (c) => {
1289	          const k = keyForVolid(c, String(volume.diskName));
1290	          return !k || !k.startsWith("scsi");
1291	        });
1292	        key = keyForVolid(config, volume.diskName);
1293	      }
1294	      // Deleting an "unused" entry destroys the underlying disk.
1295	      if (key) {
1296	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
1297	      }
1298	    } catch (e: any) {
1299	      const msg = String(e?.body ?? e?.message ?? e);
1300	      if (!msg.includes("does not exist")) throw e;
1301	    }
1302	  }
1303	
1304	  await db.volume.delete({ where: { id: volume.id } });
1305	  await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
1306	}
