1	/**
2	 * Shared per-server DISK EXPANSION core — the money path for growing a single
3	 * server's OWN root disk without touching its plan's CPU/RAM/price.
4	 *
5	 * Used by the wallet flow (lib/actions-disk.ts expandServerDisk) and by the
6	 * Stripe confirm route so a paid checkout can apply the expansion immediately.
7	 * Plain server module (NOT "use server") — same shape as lib/resize.ts, and it
8	 * deliberately mirrors that file line-for-line so the two money paths can never
9	 * drift apart.
10	 *
11	 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
12	 * There is no shrink counterpart to `applyDiskExpand`, and nothing here (or
13	 * anywhere else) ever decrements `Server.extraDiskGB`.
14	 *
15	 * ─── WHY THIS CANNOT DOUBLE-CHARGE ──────────────────────────────────────────
16	 *  1. `diskExpandQuote` is the ONLY place the prorated amount is computed, and
17	 *     both the wallet path and the Stripe-confirm path call it.
18	 *  2. The wallet is debited exactly once, inside the same $transaction that
19	 *     creates the DISK_EXPAND job — a rolled-back debit leaves no job, and a
20	 *     job that exists was always paid for.
21	 *  3. On the card path the wallet is NOT touched until Stripe clears: checkout
22	 *     charges only the card remainder, the confirm route credits that remainder
23	 *     to the wallet and then debits the FULL proration, so the two net out.
24	 *  4. `creditCheckoutSession`'s UNIQUE(stripeSessionId) makes the confirm route
25	 *     idempotent — a reloaded/replayed confirm URL credits (and therefore
26	 *     applies) nothing a second time.
27	 *  5. `Server.extraDiskGB` is advanced by the WORKER on success, never here, so
28	 *     a failed expansion is refunded by the worker's reconcile pass and the
29	 *     customer never renews on storage they didn't get.
30	 */
31	import { db } from "./db";
32	import { debitWallet, InsufficientBalanceError } from "./wallet";
33	import { invoiceCreateData } from "./invoices";
34	import { getSettingInt } from "./settings";
35	import { diskCapacityCheck } from "./capacity";
36	import { MS_PER_AVG_MONTH } from "./resize";
37	import {
38	  EXTRA_DISK_DEFAULT_PER_GB_CENTS,
39	  EXTRA_DISK_MAX_TOTAL_GB,
40	  EXTRA_DISK_MIN_GB,
41	  EXTRA_DISK_STEP_GB,
42	  effectiveDiskGB,
43	  extraDiskCentsAt,
44	  extraDiskLabel,
45	  isValidExtraDiskAddGB,
46	} from "./extra-disk";
