60	/** Monthly charge (integer cents) for `gb` GB of extra disk at the current price. */
61	export async function extraDiskMonthlyCents(gb: number): Promise<number> {
62	  if (!gb || gb <= 0) return 0;
63	  return extraDiskCentsAt(gb, await extraDiskPerGbCents());
64	}
