66	type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
67	
68	function loadServer(serverId: string) {
69	  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
70	}
71	
72	export type DiskExpandQuote = {
73	  server: QuotedServer;
74	  /** GB being added in THIS purchase. */
75	  addGB: number;
76	  /** `extraDiskGB` the server will hold once the worker finishes. */
77	  targetExtraDiskGB: number;
78	  /** Effective disk (plan + extra) after the expansion. */
79	  newTotalDiskGB: number;
80	  perGbCents: number;
81	  /** Recurring monthly cost of the newly-added GB (billed every renewal). */
82	  monthlyCents: number;
83	  /** One-off charge for the remainder of the CURRENT paid term. */
84	  prorateCents: number;
85	};
