1	// Shared server-upgrade (RESIZE up) core — used by the wallet flow
2	// (lib/actions-server.ts resizeServer) and by the Stripe confirm route so a paid
3	// checkout can apply the upgrade immediately. Plain server module (not "use server").
4	import { db } from "./db";
5	import { debitWallet, InsufficientBalanceError } from "./wallet";
6	import { invoiceCreateData } from "./invoices";
7	import { prorateUpgradeCents, remainingMonths } from "./proration";
8	
9	/** Average calendar month in ms (365.25/12 ≈ 30.44d) for duration-based proration. */
10	export const MS_PER_AVG_MONTH = 30.44 * 86400_000;
11	
12	export class ResizeError extends Error {}
13	
14	type QuotedServer = Awaited<ReturnType<typeof loadServer>>;
15	type QuotedPlan = NonNullable<Awaited<ReturnType<typeof loadPlan>>>;
16	
17	function loadServer(serverId: string) {
18	  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
19	}
20	function loadPlan(planId: string) {
21	  return db.plan.findUnique({ where: { id: planId } });
22	}
23	
24	export type ResizeQuote = {
25	  server: NonNullable<QuotedServer>;
26	  newPlan: QuotedPlan;
27	  prorateCents: number;
28	};
29	
30	/**
31	 * Validate an UPGRADE and compute the prorated charge over the ACTUAL remaining
32	 * duration (monthly price difference for every remaining month; null expiresAt
33	 * on free/admin servers => 0). Throws ResizeError with a user-facing message on
34	 * any guard failure. Does NOT check ownership — callers must do that.
35	 *
36	 * ─── INTERACTION WITH PER-SERVER EXTRA DISK ─────────────────────────────────
37	 * `Server.extraDiskGB` (disk bought via the deploy upsell or "Add storage") is
38	 * ADDITIVE to whichever plan the server is on, so a plan change must leave it
39	 * completely alone. Two things follow, and both are deliberate:
40	 *
41	 *  1. NOT DOUBLE-CHARGED. The proration below is a difference of PLAN monthly
42	 *     prices. The extra-disk surcharge is identical before and after the resize
43	 *     (same GB, same per-GB price), so it cancels out of the delta exactly — it
44	 *     must never be added here. It keeps being billed, unchanged, by the renewal
45	 *     sweep, which reads `extraDiskGB` directly.
46	 *  2. NOT LOST. Nothing in the resize path writes `extraDiskGB`, and the worker's
47	 *     RESIZE handler sizes the disk to `newPlan.diskGB + server.extraDiskGB` — so
48	 *     the customer keeps every GB they paid for. (Sizing to the bare plan disk
49	 *     would ask Proxmox to SHRINK the disk of any server holding extra storage,
50	 *     and the whole resize would hard-fail.)
51	 *
52	 * The disk-grow guard below intentionally compares PLAN disks, not effective
53	 * disks: since the extra is added to both sides, a target plan with an equal or
54	 * larger disk can never shrink the effective disk.
55	 */
56	export async function resizeQuote(serverId: string, planId: string): Promise<ResizeQuote> {
57	  const server = await loadServer(serverId);
58	  if (!server) throw new ResizeError("Not found");
59	  const newPlan = await loadPlan(planId);
60	  if (!newPlan?.active) throw new ResizeError("Plan not available.");
61	  if (newPlan.id === server.planId) throw new ResizeError("Server is already on this plan.");
62	  if (newPlan.diskGB < server.plan.diskGB) {
63	    throw new ResizeError("Disk storage can only grow — choose a plan with equal or larger disk.");
64	  }
65	  if (newPlan.priceCents < server.plan.priceCents) {
66	    throw new ResizeError("Downgrades aren't self-service yet — please contact support.");
67	  }
68	  if (!["RUNNING", "STOPPED"].includes(server.status)) throw new ResizeError("Server is busy.");
69	
70	  let prorateCents = 0;
71	  if (!server.isFree && server.expiresAt) {
72	    // Price the upgrade the way a FRESH order for the target plan would be priced
73	    // today — term discount AND current promo applied. Using the raw list-price
74	    // delta (as this did until 2026-07-25) overcharged by the whole discount
75	    // stack: on a 36-month term with a 30% promo running, $1,044.45 to upgrade
76	    // versus $665.08 to simply buy the same plan outright for the same end date.
77	    // Shared with the downgrade credit and with the client picker via
78	    // lib/proration.ts so displayed, charged and credited cannot drift apart.
79	    //
80	    // `remainingMonths` covers EVERY month left on `expiresAt` and takes no cap —
81	    // see the note on it. Charging the full stacked duration here is what makes the
82	    // mirror-image downgrade credit safe to pay out over the same duration: after
83	    // this charge the customer has genuinely paid the new plan's rate for every one
84	    // of those months. Capping this side alone would mint money on a round trip;
85	    // capping the credit side alone destroyed $362.88 of it until 2026-07-26.
86	    prorateCents = prorateUpgradeCents({
87	      fromMonthlyCents: server.plan.priceCents,
88	      toMonthlyCents: newPlan.priceCents,
89	      termMonths: server.termMonths,
90	      monthsRemaining: remainingMonths(server.expiresAt, Date.now()),
91	    });
92	  }
93	  return { server, newPlan, prorateCents };
94	}
95	
96	/**
97	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
98	 * the wallet transaction + PAID invoice, and queue the RESIZE job that the worker
99	 * performs on Proxmox. Re-validates every guard (plan availability, disk-grow,
100	 * not a downgrade, steady state, one in-flight job) so it is safe to call from the
101	 * unauthenticated confirm route. Throws ResizeError on any guard failure.
102	 *
103	 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
104	 * amount the customer paid into their wallet at checkout so the debit here nets to
105	 * zero against that credit (mirrors how the deploy confirm re-runs placeOrder to
106	 * spend the just-credited funds). The wallet path omits it and debits the quote.
107	 */
108	export async function applyResize(opts: {
109	  serverId: string;
110	  planId: string;
111	  actorUserId: string;
112	  chargeCents?: number;
113	}): Promise<void> {
114	  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
115	  const prorateCents = opts.chargeCents ?? quoted;
116	
117	  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
118	  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");
119	
120	  try {
121	    await db.$transaction(async (tx) => {
122	      if (prorateCents > 0) {
123	        await debitWallet(tx, server.userId, prorateCents);
124	        await tx.walletTransaction.create({
125	          data: {
126	            userId: server.userId,
127	            amountCents: -prorateCents,
128	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
129	          },
130	        });
131	        // PAID invoice for the proration charge (one per user-initiated resize).
132	        await tx.invoice.create({
133	          data: invoiceCreateData({
134	            userId: server.userId,
135	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
136	            status: "PAID",
137	            lineItems: [
138	              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
139	            ],
140	          }),
141	        });
142	      }
143	      // Record the amount charged on the job so the worker's RESIZE handler can
144	      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
145	      // resize terminally fails — money is committed here, before the job runs.
146	      await tx.job.create({
147	        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up" } as any },
148	      });
149	      await tx.auditLog.create({
150	        data: { userId: opts.actorUserId, action: "server.resize", detail: `${server.id} -> ${newPlan.slug} prorate=${prorateCents}` },
151	      });
152	    });
153	  } catch (e) {
154	    if (e instanceof InsufficientBalanceError) throw new ResizeError("Insufficient balance — top up your wallet first.");
155	    throw e;
156	  }
157	}
