// ---------- Server lifecycle ----------

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

export async function serverAction(serverId: string, action: string) {
  const { user, server } = await ownedServer(serverId);
  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
    start: "START",
    stop: "STOP",
    reboot: "REBOOT",
    reinstall: "REINSTALL",
    delete: "DELETE",
  };
  const type = allowed[action];
  if (!type) throw new Error("Invalid action");
  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
    throw new Error("Server is suspended");
  }

  // A reinstall wipes the whole VM, including any block-storage volume the VM
  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
  //
  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
  // deliberately keeps `serverId` set so the volume can be re-attached
  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
  // Filtering on ATTACHED therefore missed the worst case: customer fills a
  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
  // Reinstall — both guards see zero attached volumes, and the purge takes the
  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
  // by serverId; this path did not. That asymmetry was the bug.
  if (type === "REINSTALL") {
    const pinnedVolumes = await db.volume.count({ where: { serverId } });
    if (pinnedVolumes > 0) {
      throw new Error(
        "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
      );
    }
  }

  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) return; // debounce: one job at a time per server

  if (type === "DELETE") {
    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
  }
  await db.job.create({ data: { type, serverId } });
  await audit(user.id, `server.${action}`, serverId);
  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
  revalidatePath(`/dashboard/servers/${serverId}`);
}

